import unittest
from ring.buffer import RingBuffer

class TestRingBuffer(unittest.TestCase):
    def test_overwrite_and_read(self):
        rb = RingBuffer(3)
        rb.write('a'); rb.write('b'); rb.write('c')
        rb.write('d')  # overwrites 'a'
        self.assertEqual(rb.read(2), ['b', 'c'])
        self.assertEqual(rb.read(2), ['d'])

if __name__ == '__main__': unittest.main()

